<?php declare(strict_types=1); $this->layout('layouts/default', compact('title','productName','activeProduct','currentPage')); $monthLabels=[1=>'Janeiro',2=>'Fevereiro',3=>'Março',4=>'Abril',5=>'Maio',6=>'Junho',7=>'Julho',8=>'Agosto',9=>'Setembro',10=>'Outubro',11=>'Novembro',12=>'Dezembro']; ?>
<main class="erp-page erp-page-period-detail"><nav class="erp-breadcrumb"><a href="/erp/periods">Competências</a><span>/</span><span><?= sprintf('%02d/%04d',(int)$period['period_month'],(int)$period['period_year']) ?></span></nav>
    <?php $this->insert('components/erp-page-header',['heading'=>sprintf('%02d/%04d',(int)$period['period_month'],(int)$period['period_year']),'description'=>(string)($period['trade_name']?:$period['legal_name']),'kicker'=>'COMPETÊNCIA · ERP','actionHref'=>'/erp/periods','actionLabel'=>'Voltar à lista']); ?>
    <section class="erp-panel erp-data-panel"><header class="erp-panel-head"><div><h2>Dados da competência</h2><p>Período civil: <?= $this->e($monthLabels[(int)$period['period_month']]??'') ?> de <?= (int)$period['period_year'] ?></p></div><span class="erp-status ativo">Aberta</span></header><dl class="erp-period-metadata"><div><dt>Condomínio</dt><dd><?= $this->e((string)($period['trade_name']?:$period['legal_name'])) ?></dd></div><div><dt>Situação</dt><dd>Aberta</dd></div><div><dt>Criada em</dt><dd><?= $this->e((string)$period['created_at']) ?></dd></div><div><dt>Criada por</dt><dd><?= $this->e((string)$period['created_by_name']) ?></dd></div><div><dt>Última atualização</dt><dd><?= $this->e((string)$period['updated_at']) ?></dd></div><div><dt>Atualizada por</dt><dd><?= $this->e((string)($period['updated_by_name']?:$period['created_by_name'])) ?></dd></div></dl><footer class="erp-table-foot">Fechamento será disponibilizado em etapa posterior.</footer></section>
    <section class="erp-panel erp-data-panel erp-period-audit"><header class="erp-panel-head"><div><h2>Histórico de auditoria</h2><p>Eventos registrados para esta competência.</p></div></header><?php if($auditEvents===[]): ?><div class="erp-empty-state"><strong>Nenhum evento de auditoria encontrado</strong></div><?php else: ?><div class="erp-table-wrap"><table><thead><tr><th>Evento</th><th>Ator</th><th>Data</th><th>Metadados</th></tr></thead><tbody><?php foreach($auditEvents as $event): ?><tr><td><?= $this->e((string)$event['event_type']) ?></td><td><?= $this->e((string)($event['actor_name']?:'Usuário #'.(int)$event['actor_user_id'])) ?></td><td><?= $this->e((string)$event['created_at']) ?></td><td><?= $this->e((string)($event['metadata']??'')) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
</main>
